import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, readFile, rm, mkdir, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const profile = await mkdtemp(path.join(os.tmpdir(), 'legendgirl-som-chrome-'));
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', ['--headless=new', '--mute-audio', '--no-first-run', '--no-default-browser-check', '--autoplay-policy=no-user-gesture-required', '--remote-debugging-port=0', '--user-data-dir='+profile, 'about:blank'], {stdio:'ignore'});
let ws;
try {
 let port;
 for(let i=0;i<100;i++) { try { port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break; } catch {} await new Promise(r=>setTimeout(r,100)); }
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await (await fetch('http://127.0.0.1:'+port+'/json/list')).json();
 ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
 await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};

 const label=process.argv[2]||'base',out='/tmp/legendgirl-revisao-'+label;await mkdir(out,{recursive:true});
 await call('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});
 await call('Page.navigate',{url:'http://127.0.0.1:3000/tests/dark-room-playthrough.html'});for(let i=0;i<300;i++){if(await evaluate('Boolean(window.review)'))break;await new Promise(r=>setTimeout(r,100));}
 const trace=await evaluate(`(async()=>{
  const g=review.game;await g.assetsReady;g.startDebugPhase('garden','NORMAL');const phase=g.state.toyRoomInstance.instance.garden;for(let i=0;i<200&&!phase.ready;i++)await new Promise(r=>setTimeout(r,50));if(!phase.ready)throw Error('Jardim indisponível');g.setPaused(true);phase.canvas.width=1280;phase.canvas.height=800;
  const {stepGarden,retryGarden}=await import('/src/js/garden/GardenSimulation.js'),{createPilot}=await import('/docs/diario-ia/qa/jardim-v2/piloto.mjs');let pilot=createPilot(),elapsed=0,next=0,retries=0,renders=0;
  window.visualReview={phase,frames:[]};const s=phase.state;const capture=()=>visualReview.frames.push(JSON.parse(JSON.stringify(s)));
  for(let tick=0;elapsed<1500&&s.stage!=='COMPLETE';tick++){
   stepGarden(s,pilot(s),1/60);elapsed+=1/60;
   if(tick%15===0){phase.render();renders++;}
   if(s.player.x>=next){capture();next=s.player.x+800;}
   if(s.stage==='GAME_OVER'){if(++retries>3)throw Error('Três derrotas no percurso');retryGarden(s);pilot=createPilot();}
   if(tick%600===0)await new Promise(r=>setTimeout(r,0));
  }
  if(s.stage!=='COMPLETE')throw Error('Percurso incompleto');capture();
  return{resultado:'percurso completo',minutos:elapsed/60,retries,renders,quadros:visualReview.frames.length};
 })()`);console.log(JSON.stringify(trace));
 const count=await evaluate('visualReview.frames.length');
 for(let first=0;first<count;first+=24){const data=await evaluate(`(()=>{
  const v=visualReview,phase=v.phase,sheet=document.createElement('canvas');sheet.width=1536;sheet.height=736;const ctx=sheet.getContext('2d');ctx.fillStyle='#f7f2e5';ctx.fillRect(0,0,sheet.width,sheet.height);ctx.font='12px sans-serif';
  for(let i=${first};i<Math.min(${first+24},v.frames.length);i++){phase.state=v.frames[i];phase.render();const cell=i-${first},x=(cell%6)*256,y=Math.floor(cell/6)*184;ctx.drawImage(phase.canvas,x,y,256,160);ctx.fillStyle='#203e28';ctx.fillText(i+' · x '+Math.round(phase.state.player.x)+' · '+phase.state.player.terrain,x+3,y+175);}
  return sheet.toDataURL();
 })()`);await writeFile(out+'/folha-'+String(first/24).padStart(2,'0')+'.png',Buffer.from(data.split(',')[1],'base64'));}
 for(const index of [2,8,20,55,100,count-1].filter(i=>i<count)){const data=await evaluate(`(()=>{visualReview.phase.state=visualReview.frames[${index}];visualReview.phase.render();return visualReview.phase.canvas.toDataURL();})()`);await writeFile(out+'/quadro-'+index+'.png',Buffer.from(data.split(',')[1],'base64'));}
 await writeFile('docs/diario-ia/qa/jardim-revisao/percurso-'+label+'.json',JSON.stringify(trace,null,2));
 await writeFile(out+'/estados.json',JSON.stringify(await evaluate('visualReview.frames')));console.log('CAPTURAS '+out);
}finally{ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
